using System;using System.IO;using System.Linq;using System.Text;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using UnityEditor;
namespace CodexOutTransfer {
 public static class OutExposureCheck {
 [MenuItem("Tools/Out Scene Transfer/Diagnose Exposure")]
 public static void Diagnose(){var b=new StringBuilder();try{b.AppendLine("active="+SceneManager.GetActiveScene().path+" linear="+QualitySettings.activeColorSpace+" quality="+QualitySettings.GetQualityLevel());for(int i=0;i<SceneManager.sceneCount;i++){var s=SceneManager.GetSceneAt(i);b.AppendLine("scene="+s.path+" loaded="+s.isLoaded+" dirty="+s.isDirty);}
 foreach(var light in UnityEngine.Object.FindObjectsOfType<Light>())b.AppendLine("LIGHT scene="+light.gameObject.scene.name+" path="+PathOf(light.transform)+" type="+light.type+" intensity="+light.intensity+" colour="+light.color+" enabled="+light.enabled+" shadows="+light.shadows+" cookie="+(light.cookie?light.cookie.name:"none"));
 b.AppendLine("ambientMode="+RenderSettings.ambientMode+" sky="+RenderSettings.ambientSkyColor+" equator="+RenderSettings.ambientEquatorColor+" ground="+RenderSettings.ambientGroundColor+" reflection="+RenderSettings.reflectionIntensity+" sun="+(RenderSettings.sun?PathOf(RenderSettings.sun.transform):"none"));
 foreach(var v in UnityEngine.Object.FindObjectsOfType<Volume>())b.AppendLine("VOLUME scene="+v.gameObject.scene.name+" name="+v.name+" priority="+v.priority+" global="+v.isGlobal+" profile="+AssetDatabase.GetAssetPath(v.sharedProfile));foreach(var c in UnityEngine.Object.FindObjectsOfType<Camera>()){var u=c.GetUniversalAdditionalCameraData();b.AppendLine("CAM scene="+c.gameObject.scene.name+" path="+PathOf(c.transform)+" post="+u.renderPostProcessing+" renderer="+u.scriptableRenderer.GetType().Name);}
 var pipeline=GraphicsSettings.currentRenderPipeline as UniversalRenderPipelineAsset;b.AppendLine("pipeline="+AssetDatabase.GetAssetPath(pipeline)+" additionalLightsMode="+pipeline.additionalLightsRenderingMode+" shadowDistance="+pipeline.shadowDistance);
 }catch(Exception e){b.AppendLine(e.ToString());}File.WriteAllText("C:/Users/lenovo/Documents/Codex/2026-10-16/new-chat/work/out_exposure_diagnosis.txt",b.ToString());}
 static string PathOf(Transform t){return t.parent?PathOf(t.parent)+"/"+t.name:t.name;}
 [MenuItem("Tools/Out Scene Transfer/Show Out Without Other Scene Lighting")]
 public static void Isolate(){var b=new StringBuilder();try{var current=SceneManager.GetActiveScene();if(current.path!="Assets/ArtStyleTest/Scenes/out.unity")throw new Exception("Select out as active scene first");var others=Enumerable.Range(0,SceneManager.sceneCount).Select(SceneManager.GetSceneAt).Where(s=>s.isLoaded&&s!=current).ToArray();foreach(var s in others)if(s.isDirty)throw new Exception("Scene contains unsaved edits; preserving it: "+s.path);foreach(var s in others){bool closed=UnityEditor.SceneManagement.EditorSceneManager.CloseScene(s,false);b.AppendLine("unloaded="+s.path+" success="+closed);if(!closed)throw new Exception("Scene did not unload");}var camera=current.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>(true)).First(c=>c.transform.parent&&c.transform.parent.name=="xiangjipingtai");
 var method=typeof(OutSceneTransfer).GetMethod("Capture",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic);method.Invoke(null,new object[]{camera,"C:/Users/lenovo/Documents/Codex/2026-10-16/new-chat/outputs/Out_scene_lighting_fixed.png"});var lights=UnityEngine.Object.FindObjectsOfType<Light>().Where(l=>l.enabled).ToArray();foreach(var l in lights)b.AppendLine("remainingLight="+l.gameObject.scene.name+"/"+l.name+" intensity="+l.intensity);if(lights.Any(l=>l.gameObject.scene!=current))throw new Exception("Other scene lighting still active");Selection.activeGameObject=current.GetRootGameObjects().FirstOrDefault(g=>g.name=="Directional Light");b.AppendLine("fixed=True p1Preserved=True outLightingValuesUnchanged=True");}catch(Exception e){b.AppendLine(e.ToString());Debug.LogException(e);}File.WriteAllText("C:/Users/lenovo/Documents/Codex/2026-10-16/new-chat/work/out_exposure_fix.txt",b.ToString());Diagnose();}
 }
}
